const long long MOD = 1e9 + 7;
long long add(long long a,long long b){ return (a+b)%MOD; }
long long sub(long long a,long long b){ return ((a-b)%MOD+MOD)%MOD; }
long long mul(long long a,long long b){ return a%MOD*(b%MOD)%MOD; }
long long power(long long a,long long n){ long long r=1;a%=MOD;
    while(n){ if(n&1) r=r*a%MOD; a=a*a%MOD; n>>=1; } return r; }
long long inv(long long a){ return power(a, MOD-2); }  // prime MOD
